      "story_big": "ציר עירוני קצר יחסית שמחבר שלוש מסורות ונוף מפרץ.\n\nמרפסת הגנים הבהאיים, יפה נוף 61: המבט העליון על תשע-עשרה הטרסות ומפרץ חיפה.\n\nחניון ציבורי יפה נוף — הליכה לטיילת לואי: מחנים בחניון הציבורי ברחוב יפה נוף וממשיכים ברגל לטיילת לואי ולתצפית המפרץ.\n\nמנזר סטלה מאריס: מרכז כרמליטי היסטורי על ראש הכרמל.\n\nהמושבה הגרמנית, שדרות בן גוריון: אדריכלות טמפלרית וציר מבט אל הגנים.",
