      "summary": "מסלול כביש שמסתיים בחניה ציבורית אחת ליד מרכז המבקרים; ארבעת אתרי עכו נשמרים כתוכן ומבוצעים ברגל בלבד.",
      "story_big": "מסלול כביש שמסתיים בחניה ציבורית אחת ליד מרכז המבקרים; ארבעת אתרי עכו נשמרים כתוכן ומבוצעים ברגל בלבד.\n\nחניה ציבורית מרכז המבקרים עכו העתיקה, ויצמן 1: זו נקודת הניווט היחידה בעכו העתיקה: מחנים כחוק ליד מרכז המבקרים ומכאן ממשיכים לכל האתרים ברגל.\n\nמוזיאון אסירי המחתרות עכו — הליכה בלבד: סיפור האסירים והמאבק בתקופת המנדט נשמר כחלק מתוכן היום, אך מגיעים אליו ברגל מן החניה.\n\nאולמות האבירים — הליכה בלבד: המרכז ההוספיטלרי הצלבני הוא תחנת תוכן מרכזית, והגישה אליו רגלית מן החניה.\n\nמנהרת הטמפלרים — הליכה בלבד: מנהרה צלבנית המחברת את הרובע הטמפלרי אל אזור הנמל; מגיעים אליה ברגל בלבד.\n\nנמל עכו — הליכה בלבד: הנמל מספר את סיפורה הימי של עכו לאורך התקופות; הוא תחנת הסיום הרגלית של הביקור.",
      "cautions": "הניווט מסתיים בחניה הציבורית ליד מרכז המבקרים, ויצמן 1. • אין להכניס אופנוע לסמטאות ואין לנווט בנפרד אל נקודות ההליכה. • בודקים שעות, כרטיסים ונגישות של כל אתר לפני היציאה.",
