      "story_big": "מסלול נחש מן המרכז דרך כפר תבור וכפר כמא אל מוזיאון התרבות הירמוכית ובית גבריאל, וחזרה בציר 90–71–6.\n\nמוזיאון המושבה כפר תבור: החקלאות וראשית ההתיישבות בגליל התחתון.\n\nהמרכז למורשת הצ׳רקסית: שפה, לבוש והגירת הצ׳רקסים לגליל.\n\nמוזיאון התרבות הירמוכית, שער הגולן: המוזיאון מציג את תרבות שער הגולן מן התקופה הנאוליתית ומאפשר תוכן פרהיסטורי נגיש על כביש, במקום ניווט לשטח עובדיה.\n\nבית גבריאל: אדריכלות מודרנית ומבט אל דרום הכנרת.",
