      "story_big": "מסלול נחש סלול בין כפר קיש למנחמיה; נחל תבור ומצפה אלות נשמרים כתוכן הליכה בלבד, והחזרה מוכרחת דרך בית שאן, נבות וכביש 6.\n\nכפר קיש: שער לרמת הבזלת ולנחל תבור.\n\nחניון נחל תבור דרך גזית: תחילת מסלול ההליכה; האופנוע נשאר בחניון.\n\nמצפה אלות סירין – נקודת הליכה, לא יעד ניווט לאופנוע: מבט לעמק הירדן ולגלעד.\n\nמרכז המושבה מנחמיה — עצירת מורשת על כביש ציבורי: עצירה קצרה במרכז המושבה ההיסטורית על גבי רחובות סלולים; אין ירידה לדרכי שטח של רמת סירין.",
