      "story_big": "ליבה ארכאולוגית בסוסיתא עם חזרה כפויה לעין גב באותו כביש מורשה; משם חוזרים למרכז דרך צמח ועמק יזרעאל. מצפה השלום נשאר כהצעה נפרדת ואינו חלק מהניווט.\n\nגן לאומי כורסי — חניית הכניסה הרשמית: מנזר ביזנטי לחוף הכנרת.\n\nשער הגישה לסוסיתא מכיוון עין גב — כביש ציבורי בלבד: נקודת מעבר שמכריחה את העלייה לסוסיתא מכיוון עין גב בלבד, בהתאם להוראות הגן הלאומי.\n\nגן לאומי סוסיתא — חניית המבקרים הרשמית: פוליס הלניסטית־רומית מעל הכנרת.\n\nמצפה השלום: מבט רחב אל הכנרת והשבר.",
