      "summary": "רכיבת כביש סביב בקעת בית צידה וכנף, עם סימון ברור של קטע העפר האסור לגרסה זו.",
      "story_big": "רכיבת כביש סביב בקעת בית צידה וכנף, עם סימון ברור של קטע העפר האסור לגרסה זו.\n\nפארק קצרין העתיקה: כפר תלמודי משוחזר.\n\nשער מושב כנף: כאן מסתיימת גרסת הכביש; המעיין מעבר לדרך עפר.\n\nצומת מעלה גמלא – חלופה סלולה לירידה למעיין: חלופה סלולה שמאפשרת להמשיך את יום הרכיבה בלי לרדת לדרך העפר של המעיין.\n\nמעיין כנף – דיר עזיז (תוכן בלבד, ללא ניווט אופנוע כביש): מעיין ובית כנסת עתיק מעבר לכשני קילומטרים של דרך עפר; אינו נכלל בגרסת הכביש.\n\nחד נס: ירידה נופית לכיוון הכנרת.",
