      "summary": "מסלול נחש ייחודי בין מחצבה וולקנית משוקמת, תופעת טבע ביער אודם ואתר מורשת קרב, עם חזרה בציר 918–91.",
      "story_big": "מסלול נחש ייחודי בין מחצבה וולקנית משוקמת, תופעת טבע ביער אודם ואתר מורשת קרב, עם חזרה בציר 918–91.\n\nפארק וולקני אביטל — כניסת המבקרים: מחצבה משוקמת החושפת שכבות געשיות וממחישה את היווצרות תילי הגעש של הגולן.\n\nחניון הג׳ובה הגדולה — תחילת השביל: חונים בחניון המסומן וממשיכים ברגל אל שקע געשי גדול ביער אודם.\n\nתל פאחר — מצפה גולני: אתר קרב ממלחמת ששת הימים עם תעלות, אנדרטה ותצפית אל צפון עמק החולה.",
      "cautions": "ערפל וקרח בחורף • הג׳ובה ברגל בלבד",
