      "summary": "לולאה מערבית בעלת שתי ליבות ייחודיות לפחות: אתר שיירת יחיעם ומוזיאון חומה ומגדל חניתה, לצד לוחמי הגטאות וראש הנקרה.",
      "story_big": "לולאה מערבית בעלת שתי ליבות ייחודיות לפחות: אתר שיירת יחיעם ומוזיאון חומה ומגדל חניתה, לצד לוחמי הגטאות וראש הנקרה.\n\nבית לוחמי הגטאות: מוזיאון שהוקם בידי ניצולי שואה ומציג התנגדות, זיכרון וחיים מחדש.\n\nאתר שיירת יחיעם — חניית האנדרטה: אתר הנצחה לקרב שיירת יחיעם במלחמת העצמאות, עם חניה מוסדרת לצד כביש 89.\n\nמוזיאון חומה ומגדל חניתה: מוזיאון בקיבוץ חניתה המספר את מבצע העלייה לקרקע ואת הגנת יישובי חומה ומגדל.\n\nאתר התיירות ראש הנקרה — חניית הכניסה: מצוק, נקרות ומנהרת הרכבת המנדטורית בתחנת סיום על כביש ציבורי.",
      "cautions": "אין כניסה ליער חניתה • אין שימוש בדרך הנוף",
