      "summary": "מסלול נחש אל מבצר נמרוד ושני מתחמי הבניאס, וממנו למוזיאון האדם הקדמון במעיין ברוך; החזרה מוכרחת דרך גונן ובית המכס העליון.",
      "story_big": "מסלול נחש אל מבצר נמרוד ושני מתחמי הבניאס, וממנו למוזיאון האדם הקדמון במעיין ברוך; החזרה מוכרחת דרך גונן ובית המכס העליון.\n\nגן לאומי מבצר נמרוד — חניית הכניסה הרשמית: מצודה הררית מעל עמק החולה.\n\nבניאס – חניון מתחם המעיינות: מקורות נחל חרמון ומקדש פאן.\n\nבניאס – חניון מתחם המפל והשביל התלוי: המפל והשביל התלוי מן החניון הנפרד.\n\nמוזיאון האדם הקדמון, מעיין ברוך: אוסף פרהיסטורי מן הגליל העליון שמוסיף למסלול ליבת תוכן עצמאית שאינה קיימת במסלול הבניאס הוותיק.",
      "cautions": "כרטיס ושעות רט״ג • מעבר בין המתחמים בכביש ציבורי",
