      "summary": "כוכב מן המרכז אל ארבע שכבות סיפור בבאר שבע: העיר המקראית, באר אברהם, בית העלמין הצבאי הבריטי ואנדרטת חטיבת הנגב.",
      "story_big": "כוכב מן המרכז אל ארבע שכבות סיפור בבאר שבע: העיר המקראית, באר אברהם, בית העלמין הצבאי הבריטי ואנדרטת חטיבת הנגב.\n\nגן לאומי תל באר שבע: תל מקראי מבוצר ומערכת מים המדגימים את התפתחות היישוב בנגב.\n\nמרכז המבקרים באר אברהם: מרכז מבקרים סביב מסורת באר אברהם וסיפורה של באר שבע כעיר מדברית.\n\nבית העלמין הצבאי הבריטי בבאר שבע: תחנת זיכרון לקרבות 1917 ולכיבוש באר שבע בידי כוחות האימפריה הבריטית ואנז״ק.\n\nאנדרטת חטיבת הנגב: יצירת הנצחה מרחבית לקרבות חטיבת הנגב ולמערכה על הדרום.",
