      "story_big": "יום עירוני-חלוצי המחבר את בית אשל, פארק נחל באר שבע, מוזאון הנגב ואנדרטת חטיבת הנגב.\n\nמצפה בית אשל: אחת משלוש המצפות שהוקמו בנגב ב-1943 ונקודת מפתח בסיפור ההתיישבות והמים.\n\nפארק נחל באר שבע: פרויקט שיקום נחל ומרחב ציבורי רחב הממחיש את הקשר בין עיר, מדבר ומים.\n\nמוזאון הנגב לאמנות: מוזאון אמנות בבית המושל העות׳מאני, בלב המתחם ההיסטורי של העיר העתיקה.\n\nאנדרטת חטיבת הנגב: סיום גבוה ושקט ליום, מול נוף העיר וסיפור הקרבות על הנגב.",
      "cautions": "בפארק ובמרכז העיר יש תנועת הולכי רגל ורוכבי אופניים. • אין להשאיר ציוד גלוי על האופנוע בעצירות עירוניות.",
      "fuel": "תדלוק בבאר שבע לפי הצורך; אין צורך להסתמך על תחנה יחידה.",
