      "story_big": "לולאה עירונית־תרבותית שמחברת מדע אינטראקטיבי, מדע היסטורי ואמנות מן המזרח התיכון בלי לחזור על אתרי נתיב אנז״ק.\n\nלונדע — מוזאון הילדים של באר שבע: מרחב התנסות אינטראקטיבי שמאפשר לדבר על למידה דרך תנועה, משחק וסקרנות.\n\nפארק קרסו למדע: מתחם מדע בבניינים היסטוריים של העיר העתיקה, עם תערוכות המדגימות עקרונות מדעיים.\n\nהמוזאון לתרבות האסלאם ועמי המזרח: המוזאון שוכן במסגד הגדול ההיסטורי ומציג אמנות ותרבות של עמי האסלאם והמזרח.",
