      "best": "סתיו עד אביב; מתאים ליום מלא בקצב רגוע.",
      "summary": "מסלול שמציג את ירוחם כקהילה ולא רק כנקודת מעבר, ואז מחבר אותה למורשת הנבטית בממשית ולפארק בדימונה.",
      "story_big": "מסלול שמציג את ירוחם כקהילה ולא רק כנקודת מעבר, ואז מחבר אותה למורשת הנבטית בממשית ולפארק בדימונה.\n\nפארק אגם ירוחם: אגם בלב המדבר ומרחב קהילתי שממחיש התאמה של יישוב לתנאי האקלים.\n\nאנדרטת המייסדים, ירוחם: אנדרטה קהילתית למייסדי ירוחם, סמוך למתחם המורשת העירוני, המספקת נקודת שיחה על ראשית היישוב.\n\nגן לאומי ממשית: עיר מסחר נבטית שממחישה חיים עירוניים משוכללים באזור צחיח.\n\nפארק בן גוריון, דימונה: עצירת התאוששות לפני העלייה צפונה והזדמנות להשוות בין שתי ערי המדבר.",
      "cautions": "בכביש 224 ייתכנו רוחות צד וחול על הכביש. • בממשית יש לבדוק שעות כניסה לפני שיוצאים מירוחם.",
