      "story_big": "יום עומק סביב חזון הנגב של דוד בן גוריון, חניון הרועה, הצריף, אחוזת הקבר והעיר עבדת.\n\nחניון הרועה: חניון על ציר 40 הקרוי לזכר ברברה פרופר, רועת הצאן משדה בוקר.\n\nצריף בן גוריון: ביתו המדברי של בן גוריון ומרכז מבקרים על חזונו לפיתוח הנגב.\n\nגן לאומי קבר בן גוריון: אחוזת הקבר צופה לנחל צין ומחברת בין הנוף המדברי לבחירתו של בן גוריון.\n\nגן לאומי עבדת: עיר דרך המדגישה כי המדבר היה ציר מסחר וחקלאות מאות שנים לפני ההתיישבות המודרנית.",
