      "summary": "לולאה מן המרכז אל יישובי כיכר סדום, חקלאות חצבה ופארק ספיר, עם חזרה דרך מצפה רמון.",
      "story_big": "לולאה מן המרכז אל יישובי כיכר סדום, חקלאות חצבה ופארק ספיר, עם חזרה דרך מצפה רמון.\n\nעין תמר: מושב בכיכר סדום שמדגים חקלאות בתנאי מליחות וחום קיצוניים.\n\nנאות הכיכר: יישוב בכיכר סדום ונקודת מבט על מפלס ים המלח, חקלאות ומדבר.\n\nמרכז ויידור, חצבה: מרכז מבקרים המסביר את חדשנות החקלאות בערבה ואת העבודה בתנאי מדבר.\n\nפארק ספיר: נווה מדבר קהילתי סביב אגם וצמחייה בערבה התיכונה.",
      "cautions": "כביש 90 חשוף לשיטפונות, חום ורוח. • לפני יציאה בודקים הודעות משטרה, מזג אוויר ומצב הכבישים.",
