      "story_big": "מסע תוכן לאורך הערבה: מרכז חקלאות בחצבה, פארק ספיר, כפר האמנים בצוקים ועצירת קהילה ביטבתה.\n\nמרכז ויידור, חצבה: חלון אל חקלאות הערבה, המחקר והטכנולוגיה שמאפשרים גידול בתנאים קיצוניים.\n\nפארק ספיר: אגם וצל בלב הערבה, תחנת מנוחה טבעית בין מקטעי הרכיבה הארוכים.\n\nכפר האמנים צוקים: קהילת יוצרים שמחברת מלאכה, מדבר ואירוח מקומי.\n\nפארק יטבתה: עצירת דרך המספרת על התיישבות, חקלאות ותעשיית מזון בערבה הדרומית.",
