      "summary": "מסלול אילתי מגוון שמתחיל בצפרות, עובר במוזאון העירוני ובחוף האלמוגים, וחוזר דרך תמנע ומצפה רמון.",
      "story_big": "מסלול אילתי מגוון שמתחיל בצפרות, עובר במוזאון העירוני ובחוף האלמוגים, וחוזר דרך תמנע ומצפה רמון.\n\nפארק הצפרות אילת: מוקד נדידה ושיקום אקולוגי בקצה מפרץ אילת.\n\nמוזאון אילת עירי: סיפור התפתחות אילת מיישוב קצה לעיר נמל ותיירות.\n\nשמורת חוף האלמוגים: שונית אלמוגים צפונית ורגישה המחייבת ביקור לפי כללי השמורה.\n\nמרכז המבקרים פארק תמנע: עצירת מורשת כרייה וגאולוגיה בדרך חזרה צפונה.",
      "cautions": "אין להשאיר ציוד רכיבה ללא השגחה בחוף. • כביש 12 וכביש 40 דורשים בדיקת פתיחה, רוח ומצב ביטחוני.",
