      "story_big": "רצף היסטורי מן המצור האשורי בלכיש אל קרבות 1948 במצודת יואב ובנגבה, וסיום בבית גוברין.\n\nגן לאומי תל לכיש: עיר מבצר מקראית, סוללת מצור אשורית ומכתבי לכיש.\n\nמצודת יואב: משטרת עיראק סווידאן וסיפור הקרבות לפריצת הדרך לנגב.\n\nנגבה: קיבוץ שנאבק במצור ובקרבות 1948, עם מרחב הנצחה פתוח.\n\nגן לאומי בית גוברין: מערות, מחצבות ועיר רומית-ביזנטית בלב השפלה.",
