      "story_big": "מסלול ערד–יתיר עם תל ערד וחורשת רן; הליבה תקינה אם נשארים על האספלט ומדלגים על דרכי היער.\n\nגן לאומי תל ערד: עיר כנענית ומצודה מתקופת ממלכת יהודה.\n\nיער יתיר — נקודת ניווט כללית: היער הנטוע הגדול באזור ספר המדבר; נקודת המפה היא כללית ולא אישור לדרך פנימית.\n\nחורשת רן: עצירת יער מדברי נגישה סמוך לערד.\n\nמרכז ג׳ו אלון: תחנת סיום לתרבות הבדואים ומורשת הנגב.",
