      "summary": "שתי סגירות מהותיות מוצגות בגלוי, אך המסלול המעשי נשאר יום הנצחה סלול בין תום ותומר לגברעם.",
      "story_big": "שתי סגירות מהותיות מוצגות בגלוי, אך המסלול המעשי נשאר יום הנצחה סלול בין תום ותומר לגברעם.\n\nיער פלוגות — סגור, תיעוד בלבד: קק״ל פרסמה שהיער סגור לציבור; הנקודה נשמרת כדי להסביר מדוע אינה מופיעה בניווט.\n\nיער קוממיות — שביל הכפר סגור, תיעוד בלבד: שביל הכפר ואתר המחצבה ביער קוממיות מתועדים כחסם בלבד ואינם יעד רכיבה.\n\nמצפה תום ותומר: גן הנצחה לזכר 73 חללי אסון המסוקים, עם תצפית ושבילי ביקור מן החניה.\n\nאנדרטת חללי צוק איתן, יער גברעם: אתר הנצחה קהילתי ביער גברעם לחללי מבצע צוק איתן, הנגיש מן הציר המקומי.",
      "cautions": "אין לנווט או להיכנס ליער פלוגות ולשביל הכפר ביער קוממיות. • אם הוראות הביטחון משתנות, מבטלים או מקצרים את המסלול.",
