      "story_big": "הגרסה הבטוחה מחברת את מורשת יד מרדכי לגבעת הכלניות, ומציגה בגלוי שתי נקודות מורשת שאסורות לכניסה.\n\nבארות יצחק הישנה — שטח צבאי סגור, תיעוד בלבד: מגדל המים ושרידי הקיבוץ הישן מתעדים את קרבות 1948, אך האתר אינו פתוח לביקור.\n\nיער אסף שמחוני — סגור, תיעוד בלבד: היער ואתריו נשמרים ברשומה כדי להסביר את החסם העדכני ולא כדי להציע כניסה.\n\nמוזאון יד מרדכי — משואה לתקומה: מוזאון הקיבוץ עוסק בשואה, בתקומה ובקרב יד מרדכי, בתיאום שעות ביקור.\n\nגבעת הכלניות — קברי אריאל ולילי שרון: הגבעה צופה אל חוות שקמים ובה קבריהם של אריאל ולילי שרון; מגיעים רק לחניה הציבורית.",
      "cautions": "אין להתקרב לבארות יצחק הישנה או ליער אסף שמחוני ואין לעקוף מחסום. • בגבעת הכלניות חונים רק במקום המותר ואינם נכנסים לחוות שקמים.",
