      "story_big": "מסלול חוקי לממשית, עיר אובות ועין תמר, כשהחסם במעלה עקרבים מוצג אך אינו יכול למשוך את הניווט אליו.\n\nגן לאומי ממשית: עיר נבטית־ביזנטית ובה רחובות, כנסיות ומערכות מים, נגישה מן כביש 25.\n\nמעלה עקרבים — חסם בכביש 227, תיעוד בלבד: הדרך ההיסטורית נשמרת ברשומה כדי להסביר את הניתוק בין ממשית לצפון הערבה.\n\nעיר אובות: אתר בצפון הערבה הסמוך למצד חצבה ולציר 90, שאליו מגיעים מן הדרך החוקית בלבד.\n\nעין תמר: יישוב בכיכר סדום המשמש תחנת מנוחה והמחשה להתיישבות חקלאית בתנאי מלחה וחום.",
