      "story_big": "שתי בעיות מקומיות אינן מבטלות את הערבה: המפה הבטוחה עוברת בארבע נקודות סלולות ומחזירה את הקבוצה בציר אחר.\n\nעיר אובות: נקודת מורשת סלולה בצפון הערבה, סמוך למצד חצבה ולציר 90.\n\nמרכז ויידור, חצבה: מרכז מבקרים המציג חקלאות, מים וחדשנות בערבה התיכונה.\n\nמצפור השלום בדרך השלום: תצפית סלולה אל נחל הערבה והרי אדום; נשארים בציר הסלול ובהתאם לפתיחה.\n\nמואה הנבטית — גישת עפר, תיעוד בלבד: תחנת דרך הבשמים חשובה, אך הסטייה מכביש 90 אינה מתאימה כברירת מחדל לקבוצת אופנועי כביש.\n\nחוות האנטילופות — סגורה לתיירות, תיעוד בלבד: החווה הייתה מוקד טבע ותיירות בערבה, אך מפעיליה הודיעו על סגירה לתיירות מינואר 2026.\n\nפארק ספיר: פארק קהילתי נגיש מן הכביש המשמש חלופת עצירה סלולה ומוצלת יחסית.",
      "cautions": "אין לפנות לדרך העפר למואה ואין להגיע לחוות האנטילופות הסגורה. • דרך השלום מבוצעת רק כשהיא פתוחה וללא כניסה לדרכי מאגרים או עפר.",
      "fuel": "תדלוק בבאר שבע ובערבה; השלמה במצפה רמון בחזרה.",
