      "best": "בוקר באמצע השבוע",
      "summary": "לולאה עירונית קצרה המחברת עיצוב, תצפית חוץ באתר חוסמסה, אמנות קינטית ותולדות המושבה.",
      "story_big": "לולאה עירונית קצרה המחברת עיצוב, תצפית חוץ באתר חוסמסה, אמנות קינטית ותולדות המושבה.\n\nמוזיאון העיצוב חולון: בניין רון ארד מציג עיצוב ישראלי ובינלאומי.\n\nחוסמסה, חולון — תצפית חוץ בלבד: מבנה הבאוהאוס והבאר מספרים מן החוץ על אימוני ההגנה ועל דרך הביטחון; כניסה למוזיאון נעשית רק בהזמנה מראש.\n\nמוזיאון אגם, ראשון לציון: מוזיאון המוקדש ליצירה הקינטית של יעקב אגם.\n\nמוזאון ראשון לציון: מוקד לתולדות ראשון לציון וראשית ההתיישבות העירונית.",
      "cautions": "עצירת חוסמסה במסלול היא תצפית חיצונית בלבד; כניסה למוזיאון מחייבת הזמנה מראש. • עומס עירוני וחיפוש חניה סביב המוזיאונים; עצירה רק בחניונים מוסדרים.",
