      "best": "בוקר באמצע השבוע או שישי מוקדם",
      "summary": "מסלול רב־תקופתי בין פסיפס רומי, תצפית חוץ על חאן ממלוכי ומאגר מים עבאסי.",
      "story_big": "מסלול רב־תקופתי בין פסיפס רומי, תצפית חוץ על חאן ממלוכי ומאגר מים עבאסי.\n\nמרכז פסיפס לוד: פסיפס וילה מן התקופות הרומית והביזנטית שהוצג בעולם וחזר ללוד.\n\nחאן אל־חילו, לוד — תצפית חוץ בלבד: העצירה מתבצעת מן המרחב הציבורי הסמוך לחאן ההיסטורי; אין להיכנס למתחם סגור או לעבודות.\n\nבריכת הקשתות, רמלה: מאגר מים תת־קרקעי עבאסי שנבנה בשנת 789.\n\nשוק רמלה: שוק עירוני ותיק בלב רמלה, מתאים להפסקת אוכל קצרה.",
      "cautions": "חאן אל־חילו הוא עצירת חוץ בלבד; אין להיכנס לשטח סגור או לאזור עבודות. • רחובות העיר העתיקה והשוק עמוסים בהולכי רגל; חניה מוסדרת בלבד.",
      "fuel": "תדלוק באיירפורט סיטי, לוד ורמלה.",
