      "story_big": "מסלול נחש צפוני: עולים ברצף דרך אילנות ונתניה אל החאן ופארק נחל חדרה, וחוזרים למרכז דרך השרון המזרחי.\n\nאילנות — גן בוטני יערני: ארבורטום אילנות משמר אוסף עצים עולמי במסלולים מסומנים.\n\nבית הבאר, נתניה: בית באר מספר את סיפור הפרדסים וההתיישבות בנתניה.\n\nחזית אתר לאומי החאן בחדרה — עצירת חוץ: עצירת החוץ מציגה את אחד המבנים המרכזיים מראשית חדרה; כניסת קבוצה למוזיאון דורשת תיאום מראש.\n\nחניון פארק נחל חדרה: פארק נחל חדרה מציג את שפך הנחל ושיקום סביבתי.",
