      "best": "אביב, סתיו ובוקר קיץ מוקדם",
      "summary": "לולאת חוף קצרה בין יבנה המודרנית, עיר הנמל הקדומה ושפך נחל שורק.",
      "story_big": "לולאת חוף קצרה בין יבנה המודרנית, עיר הנמל הקדומה ושפך נחל שורק.\n\nגן לאומי חוף פלמחים: הגן הלאומי משלב חוף טבעי, רכס כורכר ואתרי עתיקות.\n\nחורבת יבנה־ים: יבנה־ים הייתה עיר נמל חשובה בתקופות קדומות.\n\nמסלול שפך נחל שורק: שפך שורק הוא מפגש של נחל, דיונות וים.\n\nתחנת רכבת יבנה מערב: תחנת יבנה מערב היא נקודת איסוף ברורה סמוך לציר הראשי.",
      "cautions": "רוח צד וחול סמוך לחוף; אין לרכוב בשבילי החול של הגן הלאומי.",
