      "summary": "לולאת חוף בין תצפית גבעת יונה, פארק אשדוד־ים, שפך נחל שורק ותל יבנה־ים.",
      "story_big": "לולאת חוף בין תצפית גבעת יונה, פארק אשדוד־ים, שפך נחל שורק ותל יבנה־ים.\n\nגבעת יונה, אשדוד: גבעת יונה היא הנקודה הגבוהה באשדוד ומציעה תצפית אל הנמל, העיר והים.\n\nפארק אשדוד־ים: פארק אשדוד־ים הוא מרחב ציבורי פתוח סמוך לרצועת החוף.\n\nמסלול שפך נחל שורק: שפך נחל שורק מציג מפגש של נחל, דיונות וצמחיית חוף סמוך לפלמחים.\n\nחורבת יבנה־ים: תל יבנה־ים משמר שרידי יישוב ונמל קדום על רכס הכורכר.",
