      "story_big": "לולאה ארכאולוגית מן הפסיפס הרומי בלוד דרך מודיעין העתיקה אל מעבר אפק.\n\nמרכז פסיפס לוד: הפסיפס הרומי בלוד מציג עולם ימי ובעלי חיים ברצפה מונומנטלית.\n\nמוזיאון מורשת החשמונאים, מודיעין: מוזיאון מורשת החשמונאים מציג את הממצא הארכאולוגי ואת התפתחות מודיעין.\n\nפארק ענבה, מודיעין: פארק ענבה הוא ציר נופי בלב מודיעין ונקודת מנוחה מסודרת.\n\nגן לאומי ירקון — מתחם תל אפק: תל אפק ואנטיפטריס שלטו במעבר הצר שבין ההר למישור החוף.",
