      "story_big": "מסלול נחש הררי: עולים מן המרכז דרך בית שמש, נס הרים ודרום ירושלים, וחוזרים בציר נפרד דרך שורש וכביש 1.\n\nבר בהר — חניון נס הרים: בר בהר הוא שער לנופי נחל שורק ונס הרים.\n\nעמק הצבאים, ירושלים: עמק הצבאים משמר עדר צבאים ומערכת אקולוגית בלב העיר.\n\nטיילת האס, ירושלים: טיילת האס פותחת מבט אל העיר העתיקה ומדבר יהודה.\n\nהתחנה הראשונה, ירושלים: תחנת הרכבת העות׳מאנית הפכה למתחם תרבות פתוח.\n\nקיבוץ רמת רחל: רמת רחל יושבת על קו הרכס הדרומי של ירושלים.",
