      "summary": "יום תרבות מרוכז בגבעת רם עם חזרה למרכז דרך 443.",
      "story_big": "יום תרבות מרוכז בגבעת רם עם חזרה למרכז דרך 443.\n\nמוזיאון ישראל, ירושלים: המוזיאון הלאומי מציג ארכאולוגיה, אמנות ומגילות מדבר יהודה.\n\nמוזיאון ארצות המקרא, ירושלים: מוזיאון ארצות המקרא מציב את תרבויות המזרח הקדום בהקשר אזורי.\n\nהגן הבוטני, גבעת רם: הגן הבוטני מציג אוספי צמחים מאזורי אקלים שונים.\n\nגן סאקר, ירושלים: גן סאקר הוא נקודת מנוחה פתוחה סמוך לקריית הלאום.",
