      "best": "חורף ואביב; בוקר",
      "summary": "מסלול נחש ירוק מדרום לצפון בין חירייה המשוקמת, הפארק הלאומי, ראש ציפור והאגם האקולוגי.",
      "story_big": "מסלול נחש ירוק מדרום לצפון בין חירייה המשוקמת, הפארק הלאומי, ראש ציפור והאגם האקולוגי.\n\nפארק אריאל שרון: אתר הפסולת חירייה הפך לחלק מפארק מטרופוליני רחב.\n\nהפארק הלאומי, רמת גן: הפארק הלאומי רמת גן הוא מרחב פנאי מרכזי בגוש דן.\n\nראש ציפור, תל אביב: ראש ציפור הוא חיבור ירוק בין הירקון לנחל איילון.\n\nהפארק האקולוגי הוד השרון: האגם האקולוגי הוא חלק ממערכת השבת מים לנחל הירקון.",
      "cautions": "האתרים מיועדים להולכי רגל; האופנוע נשאר בחניון בכל פארק.",
