      "best": "בוקר באמצע השבוע, לאחר בדיקת שעות ותיאום קבוצתי לפי הצורך.",
      "summary": "מסלול נחש היסטורי: עולים מאבן יהודה דרך נתניה ואביחיל, פונים מזרחה לאילנות וחוזרים למרכז דרך כפר סבא.",
      "story_big": "מסלול נחש היסטורי: עולים מאבן יהודה דרך נתניה ואביחיל, פונים מזרחה לאילנות וחוזרים למרכז דרך כפר סבא.\n\nמוזיאון הראשונים, אבן יהודה: מוזיאון הראשונים משמר את סיפור המושבה אבן יהודה; האתר מפרסם שעות קבלת קהל, וסיור מודרך לקבוצה מחייב תיאום.\n\nמוזיאון העיר נתניה: מוזיאון העיר מתעד את התפתחות נתניה ופועל כמוזיאון וכארכיון ציבורי; לקבוצה יש לבדוק שעות ותיאום.\n\nמוזיאון בית הגדודים, אביחיל: בית הגדודים מנציח את הגדודים העבריים ואת המתנדבים לצבא הבריטי.\n\nאילנות — גן בוטני יערני: אילנות משלים את היום באוסף עצים נגיש ומסומן.",
      "cautions": "סיור מודרך קבוצתי במוזיאון הראשונים דורש תיאום; ביקור עצמאי נעשה רק בשעות שמפרסם האתר. • יש לבדוק שעות עדכניות במוזיאון העיר נתניה ובבית הגדודים לפני היציאה.",
