      "best": "אמצע שבוע לאחר קבלת אישורי ביקור",
      "summary": "לולאה תרבותית ממקווה ישראל אל מוזיאון העיצוב, מוזיאון הפלמ״ח ומוזיאון ארץ ישראל.",
      "story_big": "לולאה תרבותית ממקווה ישראל אל מוזיאון העיצוב, מוזיאון הפלמ״ח ומוזיאון ארץ ישראל.\n\nבית הספר החקלאי מקוה ישראל: מקווה ישראל הוא בית הספר החקלאי הראשון בארץ ומוקד בתולדות החינוך וההתיישבות.\n\nמוזיאון העיצוב חולון: מוזיאון העיצוב חולון מציג תערוכות עיצוב במבנה האיקוני של רון ארד.\n\nמוזיאון הפלמ״ח: מוזיאון הפלמ״ח מספר את סיפור הארגון במסלול תצוגה קבוצתי מתואם.\n\nמוזיאון ארץ ישראל, תל אביב: מוזיאון ארץ ישראל מחבר ארכאולוגיה, מלאכות ותרבות חומרית.",
