      "summary": "לולאת מורשת מדע, מחתרת ומושבות דרום השפלה.",
      "story_big": "לולאת מורשת מדע, מחתרת ומושבות דרום השפלה.\n\nמוזאון מכון איילון, רחובות: מפעל תחמושת מחתרתי שפעל מתחת למכבסה בגבעת הקיבוצים.\n\nבית ויצמן, רחובות: ביתם של חיים וורה ויצמן בלב מכון ויצמן.\n\nמוזיאון המושבה מזכרת בתיה: המוזיאון מתעד את מזכרת בתיה ומושבות הברון.\n\nמוזיאון גדרה והביל״ויים: המוזיאון מציג את סיפור גדרה והביל״ויים.",
      "cautions": "כניסה למכון איילון רק עם הזמנה מאושרת.",
