      "summary": "מסלול נחש בשרון: עולים ברצף מאפולוניה דרך נתניה ואביחיל אל הטכנודע בחדרה, וחוזרים למרכז דרך כפר סבא.",
      "story_big": "מסלול נחש בשרון: עולים ברצף מאפולוניה דרך נתניה ואביחיל אל הטכנודע בחדרה, וחוזרים למרכז דרך כפר סבא.\n\nגן לאומי אפולוניה: אפולוניה מציגה מצודה צלבנית ושרידי עיר חוף מעל מצוק השרון.\n\nבית הבאר, נתניה: בית הבאר מתעד את ראשית נתניה ואת המעבר מחקלאות להקמת עיר.\n\nמוזיאון בית הגדודים, אביחיל: בית הגדודים מציג את סיפור הגדודים העבריים וההתנדבות לצבא הבריטי.\n\nטכנודע חדרה: הטכנודע מציע תצוגות מדע, רפואה ואסטרונומיה בגבעת אולגה.",
      "cautions": "אין להגיע לטכנודע מתוך הנחה שאפשר לקנות כרטיס בקופה.",
