      "roads": "441, 4, 461, 1, 2, 20, ילדי טהרן, אברהם בר",
      "return_roads": "2, 20, 441, חיים לבנון, שדרות רוקח, דרך נמיר, הרב שלמה גורן, פנחס ספיר",
      "best": "אמצע שבוע לאחר תיאום מראש",
      "summary": "לולאה עירונית בין מוזיאוני ההגנה, האצ״ל, האמנות והפלמ״ח, עם נקודות מפגש נגישות מדרום ומצפון.",
      "story_big": "לולאה עירונית בין מוזיאוני ההגנה, האצ״ל, האמנות והפלמ״ח, עם נקודות מפגש נגישות מדרום ומצפון.\n\nמוזיאון ההגנה — רוטשילד 23: בית אליהו גולומב מציג את התפתחות ארגון ההגנה ואת דרכו של היישוב להגנה עצמית.\n\nמוזיאון האצ״ל בתש״ח: בית גידי מתמקד במערכה של האצ״ל במלחמת העצמאות ובקרב על יפו.\n\nמוזיאון תל אביב לאמנות: מוזיאון תל אביב יוצר הפוגה תרבותית בין תחנות המורשת העירוניות.\n\nמוזיאון הפלמ״ח: התצוגה החווייתית מספרת את סיפור דור הפלמ״ח ומלווה את המבקר במסלול קבוצתי.",
      "cautions": "הכניסה למוזיאון הפלמ״ח מחייבת תיאום מראש. • חניה ונסיעה במרכז תל אביב תלויות בעומס ובמגבלות מקומיות.",
      "fuel": "תחנות דלק זמינות לאורך נתיבי איילון ובגוש דן.",
