      "return_roads": "1, 417, 4173, 4171, 4180, 50, 16, 431",
      "best": "בוקר קריר לאחר בדיקת שעות שני האתרים",
      "summary": "מסלול נחש ארוך: עולים ממערת הנטיפים דרך דרום ירושלים אל השומרוני הטוב, וחוזרים למרכז בציר מערבי נפרד.",
      "story_big": "מסלול נחש ארוך: עולים ממערת הנטיפים דרך דרום ירושלים אל השומרוני הטוב, וחוזרים למרכז בציר מערבי נפרד.\n\nשמורת טבע מערת הנטיפים — חניון עליון: הניווט מסתיים בחניון העליון ובקופות; הכניסה למערה דורשת תיאום ביקור מראש והמשך הביקור נעשה ברגל במדרגות.\n\nעמק הצבאים, ירושלים: עמק הצבאים משמר מערכת אקולוגית ועדר צבאים בלב ירושלים.\n\nמרכז מורשת בגין: מרכז בגין מציג את דרכו הציבורית של מנחם בגין ואת צמתי המחתרת והמדינה.\n\nמוזיאון השומרוני הטוב: מוזיאון השומרוני הטוב מציג פסיפסים וממצאים מן הדרך ההיסטורית מירושלים ליריחו.",
      "cautions": "מנווטים לחניון העליון במערת הנטיפים; הירידה ברגל תלולה, החניון התחתון אינו יעד רגיל ונדרש אישור ביקור במערה. • יש להחזיק אישורי הזמנה למערת הנטיפים ולמרכז בגין ורישום למוזיאון השומרוני הטוב לפני היציאה. • בודקים שעות פתיחה, מזג אוויר והודעות ביטחון ביום הטיול.",
      "fuel": "תדלוק בבית שמש או בשער הגיא, והשלמה בירושלים לפני היציאה מזרחה.",
