      "km": "כ־120.3 ק״מ במסלול המלא מן המרכז ובחזרה",
      "km_num": 120.3,
      "core_km_num": 57.9,
      "style": "כפרי והיסטורי",
      "level": "בינוני",
      "start": "סינמה סיטי ראשון לציון",
      "end": "סינמה סיטי ראשון לציון",
      "roads": "441, 4, 44, 4245, 4241, 3, 424, 1",
      "return_roads": "443, 444, 453, 40, 1, 412, 441, שרון",
      "best": "רק לאחר הודעת פתיחה רשמית של קק״ל",
      "summary": "לולאה היסטורית בין תל גזר, פארק קנדה, יד לשריון ונאות קדומים; כרגע היא אינה כשירה לביצוע מלא.",
      "story_big": "לולאה היסטורית בין תל גזר, פארק קנדה, יד לשריון ונאות קדומים; כרגע היא אינה כשירה לביצוע מלא.\n\nגן לאומי תל גזר: תל גזר משמר שכבות של עיר כנענית ומקראית ששלטה על צומת דרכים מרכזי.\n\nפארק איילון־קנדה: פארק איילון־קנדה משלב יער, טרסות ושרידים לאורך עמק איילון, אך הוא סגור כעת.\n\nיד לשריון, לטרון: יד לשריון מציג את מורשת חיל השריון וממקם אותה בזירת לטרון.\n\nחניון פורצי הדרך לירושלים, פארק רבין: חניון קק״ל נגיש בכביש, ובמרחק הליכה קצר נמצאת אנדרטת פורצי הדרך לירושלים.\n\nצומת נאות קדומים — גישה לפארק: צומת נאות קדומים היא נקודת הגישה הברורה לפארק התנ״כי ולכביש החזרה למרכז.",
      "cautions": "פארק איילון־קנדה סגור ומוחרג מן הניווט; אין להיכנס אליו עד הודעת פתיחה רשמית. • החלופה החיה משתמשת רק בחניונים ובכבישים החוקיים של תל גזר, לטרון, פארק רבין ונאות קדומים.",
      "fuel": "תדלוק ברמלה או באזור לטרון.",
