      "summary": "לולאה מהמרכז דרך תל גזר ויער חולדה אל אתרי המדע והמחתרות ברחובות; כרגע אינה כשירה בשל סגירת היער.",
      "story_big": "לולאה מהמרכז דרך תל גזר ויער חולדה אל אתרי המדע והמחתרות ברחובות; כרגע אינה כשירה בשל סגירת היער.\n\nגן לאומי תל גזר: תל גזר פותח את המסלול בתצפית על מרחב השפלה ובשרידי עיר מבוצרת.\n\nבית הרצל, יער חולדה: בית הרצל ויער חולדה מספרים את סיפור ההתיישבות והייעור, אך המתחם סגור כעת.\n\nמצפה בקוע, יער המגינים: מצפה בקוע הוא הנקודה הגבוהה ביער המגינים ונמצא על דרך שקק״ל מתארת כעבירה לרכב פרטי.\n\nמוזאון מכון איילון, רחובות: מכון איילון שימר את מפעל התחמושת הסודי שפעל מתחת לקרקע.\n\nבית ויצמן, רחובות: בית ויצמן מציג את ביתם של חיים וורה ויצמן ואת ראשית מוסדות המדינה והמדע.\n\nפארק המייסדים, רחובות: פארק ציבורי בלב רחובות ובו שילוט המספר את סיפור הגן הציבורי הראשון של המושבה.",
