      "summary": "לולאה עירונית המחברת כלכלה, שוק ההון, אמנות וארכאולוגיה בתל אביב.",
      "story_big": "לולאה עירונית המחברת כלכלה, שוק ההון, אמנות וארכאולוגיה בתל אביב.\n\nמרכז המבקרים של בנק ישראל — לילינבלום 37: מרכז המבקרים מציג את תפקידי בנק ישראל, הכסף והמערכת הפיננסית.\n\nהבורסה לניירות ערך בתל אביב: בניין הבורסה מסמן את מרכז הפעילות של שוק ההון הישראלי; העצירה היא חיצונית אלא אם תואם ביקור.\n\nמוזיאון תל אביב לאמנות: מוזיאון תל אביב מציג אמנות ישראלית ובין־לאומית בלב מרכז התרבות העירוני.\n\nמוזיאון ארץ ישראל, תל אביב: מוזיאון ארץ ישראל מחבר ארכאולוגיה, תרבות חומרית ותולדות הארץ.",
      "cautions": "אין להניח שניתן להיכנס למרכז המבקרים ללא הרשמה מאושרת. • יש לבדוק חניה מוסדרת לכל תחנה ולא לעצור בנתיבי תחבורה ציבורית.",
