      "best": "אמצע שבוע לאחר הזמנת מועד לספרייה",
      "summary": "יום תוכן בירושלים בין הספרייה הלאומית, בית המשפט העליון, התחנה ההיסטורית ומרכז בגין. מבנה המסלול מסווג בכנות כהלוך וחזור, מפני שקטע המרכז–ירושלים משותף ברובו לשני הכיוונים.",
      "story_big": "יום תוכן בירושלים בין הספרייה הלאומית, בית המשפט העליון, התחנה ההיסטורית ומרכז בגין. מבנה המסלול מסווג בכנות כהלוך וחזור, מפני שקטע המרכז–ירושלים משותף ברובו לשני הכיוונים.\n\nהספרייה הלאומית, קפלן 1: הספרייה הלאומית מרכזת אוספים המתעדים את העם היהודי, מדינת ישראל ותרבויות האזור.\n\nבית המשפט העליון: בניין בית המשפט העליון משלב אדריכלות סמלית עם תפקידו בראש מערכת השיפוט.\n\nהתחנה הראשונה, ירושלים: מתחם התחנה משמר את תחנת הרכבת העות׳מאנית שחיברה את יפו לירושלים.\n\nמרכז מורשת בגין: מרכז בגין מציג את חייו ופועלו של מנחם בגין ואת פרקי המחתרת והמדינה.",
      "cautions": "הכניסה למוסדות ציבור כפופה לבידוק, שעות ומועדים. • יש להשתמש בחניה מוסדרת ולא לעצור ברחובות קריית הלאום.",
