      "story_big": "לולאה בין הכנסת, הספרייה הלאומית, בית המשפט העליון ועמק הצבאים. מבנה המסלול מסווג בכנות כהלוך וחזור, מפני שקטע המרכז–ירושלים משותף ברובו לשני הכיוונים.\n\nהספרייה הלאומית, קפלן 1: הספרייה הלאומית מרכזת אוספים המתעדים את העם היהודי, ישראל ותרבויות האזור.\n\nבית המשפט העליון: בית המשפט העליון משלב תפקיד ציבורי מרכזי עם אדריכלות סמלית.\n\nמשכן הכנסת: משכן הכנסת הוא בית המחוקקים של ישראל ומציג את עבודת הדמוקרטיה הפרלמנטרית.\n\nעמק הצבאים, ירושלים: עמק הצבאים הוא מרחב טבע עירוני פתוח המסיים את יום המוסדות מחוץ למבנים.",
      "cautions": "יש להגיע בזמן לבידוק ולהצטייד בתעודה מזהה לפי הנחיות הכנסת. • חניה לאופנועים רק במקומות המותרים.",
      "fuel": "תדלוק בשער הגיא או בכניסה לירושלים.",
