      "summary": "לולאה ירושלמית בין מרכז בגין, התחנה הראשונה, עמק הצבאים ומוזיאון ישראל. מבנה המסלול מסווג בכנות כהלוך וחזור, מפני שקטע המרכז–ירושלים משותף ברובו לשני הכיוונים.",
      "story_big": "לולאה ירושלמית בין מרכז בגין, התחנה הראשונה, עמק הצבאים ומוזיאון ישראל. מבנה המסלול מסווג בכנות כהלוך וחזור, מפני שקטע המרכז–ירושלים משותף ברובו לשני הכיוונים.\n\nמרכז מורשת בגין: מרכז בגין עוסק במנהיגותו של מנחם בגין ובצמתים מרכזיים בתולדות המדינה.\n\nהתחנה הראשונה, ירושלים: התחנה הראשונה שימרה את תוואי הרכבת ההיסטורית והפכה למרחב תרבות.\n\nעמק הצבאים, ירושלים: עמק הצבאים משמר מערכת אקולוגית עירונית ועדר צבאים בלב ירושלים.\n\nמוזיאון ישראל, ירושלים: מוזיאון ישראל משלים את היום באוספי אמנות, ארכאולוגיה ותרבות יהודית.",
      "cautions": "יש לבדוק שעות פתיחה נפרדות לכל מוסד. • בעמק הצבאים הולכים ברגל בלבד ונשארים בשבילים המסומנים.",
