      "roads": "441, 42, 431, 1, 16, 60, מעלה השלום",
      "return_roads": "60, 386, 395, 44, 431, 20, 441",
      "best": "בוקר לאחר הזמנת שעה למנהרות",
      "summary": "רכיבה מירושלים אל חניה חוקית ומאומתת, ולאחריה סיור רגלי רציף בין עיר דוד, שער האשפות, מרכז דוידסון והכותל.",
      "story_big": "רכיבה מירושלים אל חניה חוקית ומאומתת, ולאחריה סיור רגלי רציף בין עיר דוד, שער האשפות, מרכז דוידסון והכותל.\n\nמתחם התחנה הראשונה — חניה ושאטל לעיר דוד: מתחם התחנה הראשונה הוא נקודת חניה חוקית; עיר דוד מפרסמת ממנו שאטל וממליצה להגיע רגלית או בהסעה לאגן העיר העתיקה.\n\nחניון הר ציון וקבר דוד — חניה לפני המקטע הרגלי: עיר דוד ממליצה על חניון הר ציון/קבר דוד כנקודת חניה בתשלום לפני הליכה של כתשע דקות, ומזהירה שמספר המקומות מוגבל.\n\nעיר דוד: עיר דוד מציגה את גרעין ירושלים הקדומה ואת מערכות המים והביצורים שלה.\n\nשער האשפות: שער האשפות הוא שער הגישה הקרוב לאתרי האגן הדרומי ולכותל.\n\nמרכז דוידסון: מרכז דוידסון מציג את חפירות הכותל הדרומי וסביבת הר הבית הקדומה.\n\nרחבת הכותל — גישה למנהרות: רחבת הכותל היא נקודת הכניסה לסיור המוזמן במנהרות הכותל.",
      "cautions": "אין לרכוב בין נקודות הביקור הרגליות בעיר העתיקה; האופנוע נשאר בחניון המאומת. • בחניון הר ציון מספר המקומות מוגבל; מתחם התחנה הראשונה הוא חלופת חניה ושאטל. • יש להזמין מראש את מנהרות הכותל ולבדוק שעות, ביטחון וחניה ביום הביקור.",
      "fuel": "תדלוק בשער הגיא או בכניסה לירושלים לפני החניה.",
