      "start": "סינמה סיטי ראשון לציון",
      "end": "סינמה סיטי ראשון לציון",
      "roads": "441, 42, 431, 1, 417, 458, 437",
      "return_roads": "437, 1, 386, 395, 44, 431, 20, 441",
      "best": "חורף או אביב קריר, רק לאחר קבלת כל אישורי ההזמנה והרישום ובדיקת הודעות רט״ג.",
      "summary": "מסלול נחש ארוך מירושלים אל השומרוני הטוב, חניית עין מבוע ועין פרת, עם חזרה ממשית בציר מערבי דרך כביש 386 ובר בהר.",
      "story_big": "מסלול נחש ארוך מירושלים אל השומרוני הטוב, חניית עין מבוע ועין פרת, עם חזרה ממשית בציר מערבי דרך כביש 386 ובר בהר.\n\nמרכז מורשת בגין: מרכז בגין מספק פתיחת יום היסטורית לפני היציאה מזרחה למדבר יהודה.\n\nמוזיאון השומרוני הטוב: מוזיאון השומרוני הטוב מציג פסיפסים וממצאים מן האזור שבין ירושלים ליריחו.\n\nחניית עין מבוע — כניסה לשמורת נחל פרת: הניווט מסתיים בחניה הרשמית של עין מבוע, ומכאן הביקור בנחל פרת הוא רגלי ובהתאם למקטעים הפתוחים ולהרשמה מראש.\n\nשמורת טבע עין פרת — חניית מבקרים: הניווט מסתיים בחניית המבקרים החוקית של שמורת עין פרת דרך עלמון; הביקור הרגלי מתקיים רק לאחר רישום ובדיקת הודעות רט״ג.",
      "cautions": "אין לצאת בלי אישור הזמנה למרכז בגין ואישורי רישום לשומרוני הטוב, עין מבוע ועין פרת. • אין לצאת בעת התרעת שיטפונות, עומס חום, זיהום מים, סגירת מקטע או מגבלה ביטחונית. • מקטעי השמורה הם הליכה בלבד; האופנוע נשאר בחניות הכניסה החוקיות. • כבישי הגישה והחזרה צרים ומפותלים; שומרים מרווח ונמנעים מעקיפות מסוכנות.",
      "fuel": "תדלוק בירושלים לפני היציאה מזרחה; אין להסתמך על דלק בתוך השמורה.",
